const primaryImage = String($('Initialize Web Job').first().json.primaryImage ?? '');
const match = primaryImage.match(/^data:([^;]+);base64,(.+)$/s);
if (!match) {
  throw new Error('La imagen de referencia no tiene un formato data URL válido.');
}
return [{
  json: $json,
  binary: {
    reference: {
      data: match[2],
      mimeType: match[1],
      fileName: 'reference-image',
    },
  },
}];

const requestId = $('Initialize Web Job').first().json.ticket_id;
const state = $getWorkflowStaticData('global');
state.jobs ??= {};
const current = state.jobs[requestId] ?? {};
const item = $input.first();
const generated = item.json?.data?.[0];
const finalUrl = generated?.b64_json
  ? `data:image/${generated.output_format || 'jpeg'};base64,${generated.b64_json}`
  : generated?.url ?? null;
state.jobs[requestId] = {
  ...current,
  status: finalUrl ? 'completed' : 'error',
  finalUrl,
  error: finalUrl ? null : 'OpenAI no devolvió una imagen.',
  completedAt: new Date().toISOString(),
};
return [{ json: state.jobs[requestId] }];

const ticketId = String($json.query?.ticket_id ?? $json.ticket_id ?? '');
const state = $getWorkflowStaticData('global');
const job = state.jobs?.[ticketId];
return [{
  json: job
    ? { ...job, ticket_id: ticketId }
    : { status: 'processing', ticket_id: ticketId },
}];
